import type { MainNavMenuItemProps } from "./main-nav-menu.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants interface (@exp-textura/types)
const componentName = "MainNavMenu";

// Generate child element class names for the component, should match available style slots
export const MainNavMenuClasses = {
  root: "exp-textura_main-nav-menu",
  item: "exp-textura_main-nav-menu_item",
  itemIcon: "exp-textura_main-nav-menu_item_icon",
  itemLabel: "exp-textura_main-nav-menu_item_label",
  itemInlineBadge: "exp-textura_main-nav-menu_item_inline_badge",
  iconSwap: "exp-textura_main-nav-menu_icon_swap",
  iconSwapDefault: "exp-textura_main-nav-menu_icon_swap_default",
  iconSwapHover: "exp-textura_main-nav-menu_icon_swap_hover",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateItemStyles = (props: MainNavMenuItemProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<MainNavMenuItemProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    alignItems: "center",
    gap: theme.toRem(8),
    padding: `${theme.toRem(4)} ${theme.toRem(12)}`,
    borderRadius: theme.toRem(theme.border.radius.sm),
    cursor: "pointer",
    textDecoration: "none",
    color: "inherit",
    width: "100%",
    boxSizing: "border-box",
    ...theme.typography.label.md,

    [`.${MainNavMenuClasses.item}`]: {
      ...theme.typography.label.md,
      ...styleSlots?.item,
    },

    [`.${MainNavMenuClasses.itemIcon}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      flexShrink: 0,
      width: theme.toRem(20),
      height: theme.toRem(20),
      ...styleSlots?.itemIcon,
    },

    [`.${MainNavMenuClasses.iconSwap}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      width: theme.toRem(20),
      height: theme.toRem(20),
      ...styleSlots?.iconSwap,
    },

    [`.${MainNavMenuClasses.iconSwapDefault}`]: {
      display: "flex",
    },

    [`.${MainNavMenuClasses.iconSwapHover}`]: {
      display: "none",
    },

    "&:hover": {
      [`.${MainNavMenuClasses.iconSwapDefault}`]: {
        display: "none",
      },
      [`.${MainNavMenuClasses.iconSwapHover}`]: {
        display: "flex",
      },
    },

    [`.${MainNavMenuClasses.itemLabel}`]: {
      display: "flex",
      alignItems: "center",
      flex: 1,
      whiteSpace: "nowrap",
      overflow: "hidden",
      textOverflow: "ellipsis",
      ...theme.typography.label.md,
      ...styleSlots?.itemLabel,
    },

    [`.${MainNavMenuClasses.itemInlineBadge}`]: {
      marginInlineStart: "auto",
      ...styleSlots?.itemInlineBadge,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

export const StyledMainNavMenuItem = styled("a", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MainNavMenuItemProps>((props) => generateItemStyles(props));
